//! Parity tests for `nltk.tag.perceptron` and `nltk.pos_tag` against
//! fixtures generated by `parity/gen_fixtures.py`.

mod common;

use nltk::pos_tag;
use nltk::tag::{PerceptronTagger, TagOptions};
use serde::Deserialize;

use common::read_jsonl;

#[derive(Deserialize)]
struct TagRecord {
  tokens: Vec<String>,
  use_tagdict: bool,
  tags: Vec<String>,
}

#[test]
fn tag_matches_python() {
  let records: Vec<TagRecord> = read_jsonl("pos_tag.jsonl");
  let tagger = PerceptronTagger::eng();
  let mut exact = 0;
  for r in &records {
    let got: Vec<String> = tagger
      .tag(
        &r.tokens,
        TagOptions {
          use_tagdict: r.use_tagdict,
        },
      )
      .into_iter()
      .map(|(_, t)| t)
      .collect();
    assert_eq!(
      got, r.tags,
      "tokens {:?} use_tagdict={}",
      r.tokens, r.use_tagdict
    );
    exact += 1;
  }
  eprintln!("pos_tag.jsonl: {} cases, {exact} exact", records.len());
}

#[derive(Deserialize)]
struct TokenizeRecord {
  tokens: Vec<String>,
  tags: Vec<String>,
  #[serde(default)]
  surrogate: bool,
}

fn check_pos_tag(name: &str) {
  let records: Vec<TokenizeRecord> = read_jsonl(name);
  for r in &records {
    let got = pos_tag(&r.tokens);
    let words: Vec<&str> = got.iter().map(|(w, _)| w.as_str()).collect();
    let tags: Vec<&str> = got.iter().map(|(_, t)| t.as_str()).collect();
    assert_eq!(words, r.tokens);
    assert_eq!(
      tags, r.tags,
      "tokens {:?} (surrogate: {})",
      r.tokens, r.surrogate
    );
  }
  eprintln!("{name}: {} pos_tag cases, all exact", records.len());
}

#[test]
fn pos_tag_matches_python() {
  check_pos_tag("tokenize.jsonl");
}

#[test]
fn pos_tag_corpus_matches_python() {
  check_pos_tag("corpus.jsonl");
}

#[test]
fn docstring_examples() {
  let tagged = pos_tag(
    &"The quick brown fox jumps over the lazy dog"
      .split(' ')
      .collect::<Vec<_>>(),
  );
  let tags: Vec<&str> = tagged.iter().map(|(_, t)| t.as_str()).collect();
  assert_eq!(
    tags,
    ["DT", "JJ", "NN", "NN", "VBZ", "IN", "DT", "JJ", "NN"]
  );
  let tagger = PerceptronTagger::eng();
  assert_eq!(tagger.classes().len(), 45);
  assert_eq!(tagger.normalize("1999"), "!YEAR");
  assert_eq!(tagger.normalize("1999s"), "!DIGITS");
  assert_eq!(tagger.normalize("a-b"), "!HYPHEN");
  assert_eq!(tagger.normalize("-ab"), "-ab");
  assert_eq!(tagger.normalize("ABC"), "abc");
}
